import ghidra.app.script.GhidraScript;import ghidra.program.model.listing.*;import java.io.*;
public class FindNov04OccupancyFields extends GhidraScript{public void run()throws Exception{try(PrintWriter out=new PrintWriter(getScriptArgs()[0])){InstructionIterator it=currentProgram.getListing().getInstructions(true);while(it.hasNext()){Instruction i=it.next();if(!i.getMnemonicString().equals("MOV"))continue;String op=i.getDefaultOperandRepresentation(0);if(op.contains(" + 0x63]")||op.contains(" + 0x6f]")||op.contains(" + 0x70]")||op.contains(" + 0x72]")){Function f=currentProgram.getFunctionManager().getFunctionContaining(i.getAddress());out.println(i.getAddress()+" "+i+" FUNCTION "+(f==null?"null":f.getEntryPoint()+" "+f.getName()));}}}}}
